return {api_version=1,id="OG_256",name="Spawn of N'Zoth",text="<b>Deathrattle:</b> Give your minions +1/+1.",set="OG",type="minion",rarity="common",cost=3,attack=2,health=2,keywords={"deathrattle"},on_deathrattle=function(ctx,self)for _,m in ipairs(ctx:friendly_minions(self))do local dormant=false;for _,k in ipairs(ctx:entity(m).keywords)do if k=="dormant"then dormant=true;break end end;if not dormant then ctx:buff(m,1,1)end end end}
